begin;
set local statement_timeout='30s';
do $$
declare coach uuid:=gen_random_uuid(); pupil uuid:=gen_random_uuid(); stranger uuid:=gen_random_uuid();
 offer uuid:=gen_random_uuid(); j jsonb; data jsonb; pid uuid; rev integer; report_id uuid; manager uuid:=gen_random_uuid();
 access_before jsonb;
 suggestion uuid; link_suggestion uuid; decline_suggestion uuid; approved_specialty text;
begin
 perform set_config('storage.operation','object.get_authenticated',true);
 insert into auth.users(id,email,email_confirmed_at) values(coach,coach||'@directory.invalid',now()),(pupil,pupil||'@directory.invalid',now()),(stranger,stranger||'@directory.invalid',now());
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),coach,'totp','verified',now(),now());
 insert into auth.users(id,email,email_confirmed_at) values(manager,manager||'@directory.invalid',now());
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),manager,'totp','verified',now(),now());
 insert into public.admin_permissions(user_id,reason) values(manager,'Contrato transaccional del directorio');
 update public.commercial_access_settings set account_manager_user_id=manager where singleton;
 insert into public.trainer_access(trainer_id,enabled,client_limit,manual_enabled,manual_client_limit,last_reason) values(coach,true,5,true,5,'Contrato transaccional del directorio');
 update directory_private.settings set enabled=true;
 insert into commerce_private.offers(id,version,title,price_id,amount,currency,interval,capacity,directory_enabled)
 values(offer,1,'Contrato SQL transaccional','price_directoryTest',100,'EUR','month',5,false);
 insert into commerce_private.customers(owner_id) values(coach);
 insert into commerce_private.orders(owner_id,offer_id,state,paid_until) values(coach,offer,'active',now()+interval '1 day');
 insert into storage.objects(bucket_id,name) values('trainer-directory',coach||'/11111111-1111-4111-8111-111111111111.jpg');
 data:=jsonb_build_object('name','Preparador prueba','description','Carrera y fuerza para oposiciones','specialties',jsonb_build_array('Carrera'),'services',jsonb_build_array('Revisión técnica'),
 'mode','online','city','','visibility','app','photo_path',coach||'/11111111-1111-4111-8111-111111111111.jpg','email','coach@example.test','website','','whatsapp','','price','','accepting',true,'consent_version',2);
 perform set_config('request.jwt.claim.sub',coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 j:=public.directory_save(coach,0,data,false,false);
 pid:=(j->'profile'->>'id')::uuid;rev:=(j->>'revision')::integer;
 if j->>'eligible'<>'false' then raise exception 'El plan básico o regalo anuncia';end if;
 begin perform public.directory_save(coach,rev,data,true,true);raise exception 'Publicó plan excluido';exception when insufficient_privilege then null;end;
 reset role;
 update commerce_private.offers set directory_enabled=true where id=offer;
 set local role authenticated;
 begin perform public.directory_save(coach,rev,data,true,false);raise exception 'Publicó sin aceptación';exception when insufficient_privilege then null;end;
 j:=public.directory_save(coach,rev,data,true,true);rev:=(j->>'revision')::integer;
 if j->'profile'->'specialty_ids' is distinct from '["running"]'::jsonb then raise exception 'No identificó Carrera desde el cliente antiguo';end if;
 begin perform public.directory_save(coach,rev,data||jsonb_build_object('specialty_ids',array['inventada']),true,true);
   raise exception 'Aceptó una especialidad fuera del catálogo';exception when invalid_parameter_value then null;end;
 begin perform public.directory_save(coach,rev,data||jsonb_build_object('specialty_ids',array['running','running']),true,true);
   raise exception 'Aceptó una especialidad repetida';exception when invalid_parameter_value then null;end;
 perform public.directory_suggest_specialty(coach,'Orientación deportiva','Preparo competiciones');
 perform public.directory_suggest_specialty(coach,'orientacion deportiva','Reintento');
 if jsonb_array_length(public.directory_specialty_suggestions(coach,false))<>1 then raise exception 'Duplicó una sugerencia';end if;
 suggestion:=(public.directory_specialty_suggestions(coach,false)->0->>'id')::uuid;
 begin perform public.directory_specialty_suggestions(coach,true);raise exception 'Entrenador accede a la cola de ADMIN';exception when insufficient_privilege then null;end;
 begin perform public.directory_review_specialty(coach,suggestion,true,null,'Orientación deportiva','');
   raise exception 'Entrenador aprobó su propia sugerencia';exception when insufficient_privilege then null;end;
 if exists(select 1 from jsonb_array_elements(public.directory_specialty_catalog()) s where s->>'name'='Orientación deportiva') then raise exception 'La sugerencia se publicó sola';end if;
 perform public.directory_suggest_specialty(coach,'Fondo en piscina','');
 perform public.directory_suggest_specialty(coach,'Movilidad avanzada','');
 select (s->>'id')::uuid into strict link_suggestion from jsonb_array_elements(public.directory_specialty_suggestions(coach,false)) s where s->>'name'='Fondo en piscina';
 select (s->>'id')::uuid into strict decline_suggestion from jsonb_array_elements(public.directory_specialty_suggestions(coach,false)) s where s->>'name'='Movilidad avanzada';
 begin perform public.directory_save(coach,rev-1,data,false,false);raise exception 'Aceptó revisión antigua';exception when serialization_failure then null;end;
 begin perform public.directory_save(stranger,0,data,true,true);raise exception 'Suplantó propietario';exception when insufficient_privilege then null;end;
 if jsonb_array_length(public.directory_search(p_web_only=>true)->'items')<>0 then raise exception 'Solo app apareció en web';end if;
 if not exists(select 1 from storage.objects where bucket_id='trainer-directory' and name=data->>'photo_path') then raise exception 'Propietario no puede leer foto';end if;
 reset role;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"anon"}',true);
 set local role anon;
 if jsonb_array_length(public.directory_search(p_web_only=>false)->'items')<>0 then raise exception 'Anon ve solo app';end if;
 begin perform public.directory_profile(pid,false);raise exception 'Anon abre solo app';exception when insufficient_privilege then null;end;
 if exists(select 1 from storage.objects where bucket_id='trainer-directory' and name=data->>'photo_path') then raise exception 'Anon ve foto privada';end if;
 reset role;
 perform set_config('request.jwt.claim.sub',coach::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 begin perform public.directory_moderate_profile(coach,coach,true,rev,'Motivo ajeno');raise exception 'Entrenador puede moderar';exception when insufficient_privilege then null;end;
 reset role;
 perform set_config('request.jwt.claim.sub',manager::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',manager,'role','authenticated','aal','aal1')::text,true);
 set local role authenticated;
 begin perform public.directory_moderate_profile(manager,coach,true,rev,'Motivo sin MFA');raise exception 'Admin pudo moderar sin MFA';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',manager,'role','authenticated','aal','aal2')::text,true);
 j:=public.get_trainer_management_status(coach);
 access_before:=j->'access';
 if (j->'directory_moderation') is distinct from jsonb_build_object('suspended',false,'revision',rev)
   or (public.get_trainer_management_status(stranger)->'directory_moderation') is distinct from 'null'::jsonb then
   raise exception 'Estado de moderación incorrecto en la cuenta';end if;
 begin perform public.directory_moderate_profile(manager,coach,true,rev,'   ');raise exception 'Aceptó motivo vacío';exception when invalid_parameter_value then null;end;
 j:=public.directory_moderate_profile(manager,coach,true,rev,'  Suspensión sin denuncia  ');
 if j is distinct from jsonb_build_object('suspended',true,'revision',rev+1) then raise exception 'No suspendió la ficha';end if;
 begin perform public.directory_moderate_profile(manager,coach,false,rev,'Estado desfasado');raise exception 'Aceptó revisión antigua';exception when serialization_failure then null;end;
 reset role;
 if exists(select 1 from directory_private.reports where profile_id=pid)
   or not exists(select 1 from directory_private.moderation_events e
     where e.profile_id=pid and e.report_id is null and e.actor_id=manager
       and e.suspended and e.reason='Suspensión sin denuncia') then
   raise exception 'La moderación directa no guardó la decisión correctamente';end if;
 perform set_config('request.jwt.claim.sub',pupil::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 set local role authenticated;
 begin perform public.directory_profile(pid,false);raise exception 'La suspensión directa dejó abierta la ficha';exception when insufficient_privilege then null;end;
 reset role;
 perform set_config('request.jwt.claim.sub',manager::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',manager,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 j:=public.directory_moderate_profile(manager,coach,false,rev+1,'Restitución directa');
 if j is distinct from jsonb_build_object('suspended',false,'revision',rev+2)
   or (public.get_trainer_management_status(coach)->'access') is distinct from access_before then
   raise exception 'La moderación alteró el acceso profesional o no restableció la ficha';end if;
 reset role;
 perform set_config('request.jwt.claim.sub',pupil::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 set local role authenticated;
 if public.directory_profile(pid,false)->>'name'<>'Preparador prueba' then raise exception 'Usuario no puede consultar';end if;
 if jsonb_array_length(public.directory_search_with_specialties('Preparador prueba',null,'',false,null,false,array['swimming','running'])->'items')<>1
   or jsonb_array_length(public.directory_search_with_specialties('Preparador prueba',null,'',false,null,false,array['swimming','yoga'])->'items')<>0 then
   raise exception 'El filtro múltiple no usa alguna de las especialidades antes de paginar';end if;
 perform public.directory_favorite(pupil,pid,true);perform public.directory_favorite(pupil,pid,true);
 if jsonb_array_length(public.directory_search(p_favorites=>true,p_web_only=>false)->'items')<>1 then raise exception 'Favorito incorrecto';end if;
 perform public.directory_report(pupil,pid,'spam','Ensayo de denuncia');perform public.directory_report(pupil,pid,'spam','Reintento');
 if public.directory_profile(pid,false)->>'name'<>'Preparador prueba' then raise exception 'Denuncia ocultó el perfil';end if;
 begin perform public.directory_reports(pupil);raise exception 'Alumno ve denuncias';exception when insufficient_privilege then null;end;
 begin perform public.directory_favorite(stranger,pid,true);raise exception 'Cambió favoritos ajenos';exception when insufficient_privilege then null;end;
 reset role;
 if (select count(*) from directory_private.reports where reporter_id=pupil)<>1 then raise exception 'Duplicó denuncia';end if;
 select id into report_id from directory_private.reports where reporter_id=pupil;
 perform set_config('request.jwt.claim.sub',manager::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',manager,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 if jsonb_array_length(public.directory_reports(manager))<>1 then raise exception 'Responsable no ve incidencia';end if;
 if not exists(select 1 from jsonb_array_elements(public.directory_specialty_suggestions(manager,true)) s where s->>'id'=suggestion::text) then raise exception 'ADMIN no recibe la sugerencia';end if;
 perform public.directory_review_specialty(manager,suggestion,true,null,'Orientación deportiva','Gracias por sugerirla');
 perform public.directory_review_specialty(manager,link_suggestion,true,'swimming',null,'Queda dentro de Natación');
 begin perform public.directory_review_specialty(manager,decline_suggestion,false,null,null,'');
   raise exception 'Rechazó sin motivo';exception when invalid_parameter_value then null;end;
 perform public.directory_review_specialty(manager,decline_suggestion,false,null,null,'Usa el campo de presentación');
 select s->>'id' into strict approved_specialty from jsonb_array_elements(public.directory_specialty_catalog()) s where s->>'name'='Orientación deportiva';
 perform public.directory_moderate(manager,report_id,true,'Suspensión de prueba');
 reset role;
 perform set_config('request.jwt.claim.sub',coach::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 select s into strict j from jsonb_array_elements(public.directory_specialty_suggestions(coach,false)) s where s->>'id'=suggestion::text;
 if j->>'state'<>'approved' or j->>'approved_name'<>'Orientación deportiva' then raise exception 'No aparece la respuesta al entrenador';end if;
 select s into strict j from jsonb_array_elements(public.directory_specialty_suggestions(coach,false)) s where s->>'id'=link_suggestion::text;
 if j->>'state'<>'approved' or j->>'approved_name'<>'Natación' then raise exception 'No se vinculó a la especialidad existente';end if;
 select s into strict j from jsonb_array_elements(public.directory_specialty_suggestions(coach,false)) s where s->>'id'=decline_suggestion::text;
 if j->>'state'<>'declined' or j->>'note'<>'Usa el campo de presentación' then raise exception 'No se guardó el motivo del rechazo';end if;
 j:=public.directory_own(coach);
 if j->'profile'->'specialty_ids' is distinct from '["running"]'::jsonb then raise exception 'La aprobación editó la ficha automáticamente';end if;
 j:=public.directory_save(coach,(j->>'revision')::integer,data||jsonb_build_object('specialty_ids',array['running',approved_specialty]),true,true);
 if not ((j->'profile'->'specialty_ids') ? approved_specialty) then raise exception 'El entrenador no pudo marcar la especialidad aprobada';end if;
 reset role;
 if (select count(*) from directory_private.moderation_events e where e.report_id=(select r.id from directory_private.reports r where r.reporter_id=pupil))<>1 then raise exception 'Falta auditoría';end if;
 perform set_config('request.jwt.claim.sub',pupil::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 set local role authenticated;
 if jsonb_array_length(public.directory_search(p_favorites=>true,p_web_only=>false)->'items')<>0 then raise exception 'Favoritos eluden suspensión';end if;
 begin perform public.directory_profile(pid,false);raise exception 'Abre ficha suspendida';exception when insufficient_privilege then null;end;
 if exists(select 1 from storage.objects where bucket_id='trainer-directory' and name=data->>'photo_path') then raise exception 'Mantiene acceso a foto suspendida';end if;
 perform public.directory_favorite(pupil,pid,false);
 reset role;
 perform set_config('request.jwt.claim.sub',manager::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',manager,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 perform public.directory_moderate(manager,report_id,false,'Restitución de prueba');
 reset role;
 update directory_private.profiles set visibility='web' where id=pid;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"anon"}',true);
 set local role anon;
 if jsonb_array_length(public.directory_search()->'items')<>1 then raise exception 'No aparece ficha pública';end if;
 if not exists(select 1 from storage.objects where bucket_id='trainer-directory' and name=data->>'photo_path') then raise exception 'Foto web no disponible';end if;
 reset role;
 update commerce_private.orders set paid_until=now()-interval '1 second' where owner_id=coach;
 set local role anon;
 if jsonb_array_length(public.directory_search()->'items')<>0 then raise exception 'Pago caducado mantiene publicidad';end if;
 if exists(select 1 from storage.objects where bucket_id='trainer-directory' and name=data->>'photo_path') then raise exception 'Pago caducado mantiene foto';end if;
 reset role;
 if (select count(*) from directory_private.profiles where id=pid)<>1 then raise exception 'Se perdió el borrador';end if;
end $$;
rollback;
